//go:build integration

// Package events — D1 integration test.
//
// Verifies that events.Insert() writes both the notification row and the
// outbox row inside a single pgx.Tx so that a forced outbox failure rolls
// back the notification insert too.
//
// Run: go test -tags=integration -run TestInsert ./internal/events/...
package events_test

import (
	"context"
	"database/sql"
	"log/slog"
	"net/url"
	"os"
	"testing"
	"time"

	"github.com/google/uuid"
	_ "github.com/jackc/pgx/v5/stdlib"
	"github.com/stretchr/testify/require"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/modules/postgres"
	"github.com/testcontainers/testcontainers-go/wait"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	dblib "github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/events"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/migrate"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
	notifmigrations "github.com/zenithflowinc/omnicore-platform/services/notifications-svc/migrations"
)

// startTestPostgres boots a Postgres testcontainer, runs migrations, and
// returns an admin DSN (bypasses RLS) plus a pool connected as the
// notifications_app role (NOBYPASSRLS so RLS is enforced).
func startTestPostgres(t *testing.T) (adminDSN string, pool *dblib.Pool) {
	t.Helper()
	ctx := context.Background()

	pgC, err := postgres.Run(ctx,
		"postgres:16.4-alpine",
		postgres.WithDatabase("notif_events_test"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("test"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(60*time.Second),
		),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = pgC.Terminate(ctx) })

	adminDSN, err = pgC.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)

	// Apply migrations using the embedded FS.
	logger := slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelError}))
	err = migrate.Up(ctx, adminDSN, notifmigrations.FS, logger)
	require.NoError(t, err)

	// Grant a NOBYPASSRLS app role so RLS is enforced in tests.
	adminDB, err := sql.Open("pgx", adminDSN)
	require.NoError(t, err)
	defer func() { _ = adminDB.Close() }()

	_, err = adminDB.Exec(`
		DO $$ BEGIN
			IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'notifications_app') THEN
				CREATE ROLE notifications_app NOLOGIN NOBYPASSRLS;
			END IF;
		END $$`)
	require.NoError(t, err)
	_, err = adminDB.Exec(`ALTER ROLE notifications_app WITH LOGIN PASSWORD 'test_app'`)
	require.NoError(t, err)
	_, err = adminDB.Exec(`GRANT USAGE ON SCHEMA notifications TO notifications_app`)
	require.NoError(t, err)
	_, err = adminDB.Exec(`GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA notifications TO notifications_app`)
	require.NoError(t, err)
	_, err = adminDB.Exec(`GRANT USAGE ON ALL SEQUENCES IN SCHEMA notifications TO notifications_app`)
	require.NoError(t, err)

	appDSN := dsnWithUser(adminDSN, "notifications_app", "test_app")
	pool, err = dblib.NewPool(ctx, appDSN)
	require.NoError(t, err)
	t.Cleanup(pool.Close)

	return adminDSN, pool
}

// tenantCtx returns a context carrying auth.Headers for the given org+user.
func tenantCtx(orgID, userID uuid.UUID) context.Context {
	return auth.HeadersIntoContext(context.Background(), auth.Headers{
		TenantID: orgID.String(),
		UserID:   userID.String(),
	})
}

// countRows counts rows in the given fully-qualified table, bypassing RLS via
// the admin DSN (superuser).
func countRows(t *testing.T, adminDSN, table string) int {
	t.Helper()
	db, err := sql.Open("pgx", adminDSN)
	require.NoError(t, err)
	defer func() { _ = db.Close() }()
	var n int
	require.NoError(t, db.QueryRow(`SELECT count(*) FROM `+table).Scan(&n))
	return n
}

// dsnWithUser replaces the user:pass portion of a Postgres DSN.
func dsnWithUser(orig, user, pass string) string {
	u, err := url.Parse(orig)
	if err != nil {
		return orig
	}
	u.User = url.UserPassword(user, pass)
	return u.String()
}

// ---------------------------------------------------------------------------
// D1 Tests
// ---------------------------------------------------------------------------

// TestInsert_WritesNotificationAndOutboxInOneTx verifies that a successful
// Insert lands exactly one notification row and one outbox row.
func TestInsert_WritesNotificationAndOutboxInOneTx(t *testing.T) {
	if testing.Short() {
		t.Skip("integration: requires Docker")
	}
	adminDSN, pool := startTestPostgres(t)

	orgID := uuid.New()
	userID := uuid.New()
	sourceEventID := uuid.New()

	params := events.InsertParams{
		OrgID:           orgID,
		RecipientUserID: userID,
		Kind:            repo.NotificationsNotificationKindInviteAccepted,
		Title:           "Bob accepted your invite",
		Snippet:         "Bob joined your workspace",
		Monogram:        "B",
		MonogramBg:      "#1A4FD6",
		SourceEventID:   sourceEventID,
	}

	ctx := tenantCtx(orgID, userID)
	err := events.Insert(ctx, pool, params)
	require.NoError(t, err)

	require.Equal(t, 1, countRows(t, adminDSN, "notifications.notification"),
		"notification row must be written")
	require.Equal(t, 1, countRows(t, adminDSN, "notifications.event_outbox"),
		"outbox row must be written in the same tx")
}

// TestInsert_RollsBackBothOnOutboxFailure verifies transactional atomicity:
// when ForceOutboxErr is set, the outbox INSERT fails and the notification
// INSERT is also rolled back.
func TestInsert_RollsBackBothOnOutboxFailure(t *testing.T) {
	if testing.Short() {
		t.Skip("integration: requires Docker")
	}
	adminDSN, pool := startTestPostgres(t)

	orgID := uuid.New()
	userID := uuid.New()
	sourceEventID := uuid.New()

	params := events.InsertParams{
		OrgID:           orgID,
		RecipientUserID: userID,
		Kind:            repo.NotificationsNotificationKindInviteAccepted,
		Title:           "Test rollback",
		Snippet:         "This should be rolled back",
		Monogram:        "T",
		MonogramBg:      "#1A4FD6",
		SourceEventID:   sourceEventID,
		ForceOutboxErr:  true, // test-only knob: forces the outbox INSERT to fail
	}

	ctx := tenantCtx(orgID, userID)
	err := events.Insert(ctx, pool, params)
	require.Error(t, err, "Insert must return an error when outbox insert fails")

	require.Equal(t, 0, countRows(t, adminDSN, "notifications.notification"),
		"notification must be rolled back when outbox fails")
	require.Equal(t, 0, countRows(t, adminDSN, "notifications.event_outbox"),
		"outbox must also be empty (whole tx rolled back)")
}



