// Package events — unit tests for pure functions (no Docker required).
//
// These tests run in -short mode and cover computeNatsMsgID, repoKindToProto,
// NewRelayWithLogger, and natsHeaderCarrier.
package events

import (
	"log/slog"
	"os"
	"testing"

	"github.com/google/uuid"
	"github.com/nats-io/nats.go"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/proto"

	notifv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/notifications/v1"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
)

// TestComputeNatsMsgID verifies determinism, uniqueness, and length.
func TestComputeNatsMsgID(t *testing.T) {
	src := uuid.New()
	rec := uuid.New()

	id1 := computeNatsMsgID(src, rec)
	id2 := computeNatsMsgID(src, rec)
	id3 := computeNatsMsgID(uuid.New(), rec)

	require.Equal(t, id1, id2, "same inputs must produce same digest")
	require.NotEqual(t, id1, id3, "different source_event_id must produce different digest")
	require.Len(t, id1, 16, "digest must be 16 hex chars")
}

// TestRepoKindToProto verifies all enum values map correctly.
func TestRepoKindToProto(t *testing.T) {
	cases := []struct {
		in  repo.NotificationsNotificationKind
		out notifv1.NotificationKind
	}{
		{repo.NotificationsNotificationKindInviteAccepted, notifv1.NotificationKind_NOTIFICATION_KIND_INVITE_ACCEPTED},
		{repo.NotificationsNotificationKindMembershipAdded, notifv1.NotificationKind_NOTIFICATION_KIND_MEMBERSHIP_ADDED},
		{repo.NotificationsNotificationKindWorkspaceSwitched, notifv1.NotificationKind_NOTIFICATION_KIND_WORKSPACE_SWITCHED},
		{repo.NotificationsNotificationKindIngestCompleted, notifv1.NotificationKind_NOTIFICATION_KIND_INGEST_COMPLETED},
		{repo.NotificationsNotificationKindIngestFailed, notifv1.NotificationKind_NOTIFICATION_KIND_INGEST_FAILED},
		{repo.NotificationsNotificationKindRoleChanged, notifv1.NotificationKind_NOTIFICATION_KIND_ROLE_CHANGED},
		{repo.NotificationsNotificationKindLoginNewDevice, notifv1.NotificationKind_NOTIFICATION_KIND_LOGIN_NEW_DEVICE},
		{repo.NotificationsNotificationKindMessageReceived, notifv1.NotificationKind_NOTIFICATION_KIND_MESSAGE_RECEIVED},
		{"unknown_kind", notifv1.NotificationKind_NOTIFICATION_KIND_UNSPECIFIED},
	}
	for _, tc := range cases {
		got := repoKindToProto(tc.in)
		require.Equal(t, tc.out, got, "kind %q", tc.in)
	}
}

// TestNewRelayWithLogger verifies that a custom logger is accepted and the
// zero interval defaults to defaultPollInterval.
func TestNewRelayWithLogger(t *testing.T) {
	logger := slog.New(slog.NewTextHandler(os.Stderr, nil))
	relay := NewRelayWithLogger(nil, nil, 0, logger)
	require.NotNil(t, relay)
	require.Equal(t, defaultPollInterval, relay.interval)
}

// TestNewRelayWithNilLogger verifies nil logger falls back to slog.Default.
func TestNewRelayWithNilLogger(t *testing.T) {
	relay := NewRelayWithLogger(nil, nil, 0, nil)
	require.NotNil(t, relay)
}

// TestNatsHeaderCarrier verifies Set, Get, and Keys.
func TestNatsHeaderCarrier(t *testing.T) {
	h := nats.Header{}
	carrier := natsHeaderCarrier{h: h}

	carrier.Set("traceparent", "00-abc-def-01")
	require.Equal(t, "00-abc-def-01", carrier.Get("traceparent"))
	require.Nil(t, carrier.Keys(), "Keys must return nil (extract path not needed)")
}

// TestBuildPayload_WithInvalidCreatedAt verifies that buildPayload falls back
// to time.Now() when row.CreatedAt.Valid is false.
func TestBuildPayload_WithInvalidCreatedAt(t *testing.T) {
	orgID := uuid.New()
	recipientUserID := uuid.New()
	sourceEventID := uuid.New()
	natsMsgID := computeNatsMsgID(sourceEventID, recipientUserID)

	// Construct a row with CreatedAt.Valid = false (zero value of pgtype.Timestamptz).
	row := buildPayloadTestRow(orgID, recipientUserID, sourceEventID)
	// row.CreatedAt.Valid is false by default.

	b, err := buildPayload(row, orgID, recipientUserID, natsMsgID)
	require.NoError(t, err, "buildPayload must succeed with invalid CreatedAt")
	require.NotEmpty(t, b, "payload must not be empty")
}

// TestBuildPayload_SetsTargetIdFromRow verifies that buildPayload populates
// Notification.TargetId when row.TargetID is non-nil.
func TestBuildPayload_SetsTargetIdFromRow(t *testing.T) {
	orgID := uuid.New()
	recipientUserID := uuid.New()
	sourceEventID := uuid.New()
	natsMsgID := computeNatsMsgID(sourceEventID, recipientUserID)

	convID := "018f6e2a-0000-7000-8000-0000000000c0"
	row := buildPayloadTestRow(orgID, recipientUserID, sourceEventID)
	row.TargetID = &convID

	b, err := buildPayload(row, orgID, recipientUserID, natsMsgID)
	require.NoError(t, err)
	require.NotEmpty(t, b)

	var evt notifv1.NotificationCreated
	require.NoError(t, proto.Unmarshal(b, &evt))
	require.NotNil(t, evt.Notification)
	require.Equal(t, convID, evt.Notification.GetTargetId())
}

// TestBuildPayload_NilTargetID_EmptyString verifies that buildPayload sets
// Notification.TargetId to "" when row.TargetID is nil.
func TestBuildPayload_NilTargetID_EmptyString(t *testing.T) {
	orgID := uuid.New()
	recipientUserID := uuid.New()
	sourceEventID := uuid.New()
	natsMsgID := computeNatsMsgID(sourceEventID, recipientUserID)

	row := buildPayloadTestRow(orgID, recipientUserID, sourceEventID)
	// row.TargetID is nil by default.

	b, err := buildPayload(row, orgID, recipientUserID, natsMsgID)
	require.NoError(t, err)
	require.NotEmpty(t, b)

	var evt notifv1.NotificationCreated
	require.NoError(t, proto.Unmarshal(b, &evt))
	require.NotNil(t, evt.Notification)
	require.Equal(t, "", evt.Notification.GetTargetId())
}

// buildPayloadTestRow creates a minimal NotificationsNotification for testing.
func buildPayloadTestRow(orgID, recipientUserID, sourceEventID uuid.UUID) repo.NotificationsNotification {
	id, _ := uuid.NewV7()
	return repo.NotificationsNotification{
		ID:              id,
		OrgID:           orgID,
		RecipientUserID: recipientUserID,
		Kind:            repo.NotificationsNotificationKindInviteAccepted,
		Title:           "Test",
		Snippet:         "Test snippet",
		Monogram:        "T",
		MonogramBg:      "#1A4FD6",
		SourceEventID:   sourceEventID,
		NatsMsgID:       "test-msg-id",
		// CreatedAt.Valid is false (zero value).
	}
}


