// Package events wires the platform eventbus.Publisher and eventbus.Outbox
// to notifications-svc's NATS connection.
package events

import (
	"context"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/eventbus"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
)

// SetupNATS opens a NATS connection, returns a Publisher and Outbox bound to it,
// and a cleanup function the caller MUST defer at service start.
func SetupNATS(ctx context.Context, natsURL, credsFile, rootCAFile, outboxTable string) (*eventbus.Publisher, *eventbus.Outbox, func() error, error) {
	if natsURL == "" {
		return nil, nil, nil, observability.New(observability.CodeValidationFailed, "natsURL required")
	}
	// Fail-closed TLS+nkey (P0-13) via eventbus.Connect, which composes
	// natsconn.DefaultConnectOptions internally so main's indefinite-reconnect
	// posture is retained. RetryOnFailedConnect is passed explicitly to
	// preserve this call site's WithRetry choice from main -- natsconn keeps it
	// an opt-in precisely so it stays visible at the call site.
	nc, err := eventbus.Connect(ctx,
		eventbus.Config{URL: natsURL, CredsFile: credsFile, RootCAFile: rootCAFile},
		nats.RetryOnFailedConnect(true),
	)
	if err != nil {
		return nil, nil, nil, observability.Wrap(observability.CodeServiceUnavailable, "nats.Connect", err)
	}
	js, err := jetstream.New(nc)
	if err != nil {
		nc.Close()
		return nil, nil, nil, observability.Wrap(observability.CodeServiceUnavailable, "jetstream.New", err)
	}
	pub := eventbus.NewPublisher(js)
	outbox := eventbus.NewOutbox(pub, outboxTable, 0)
	cleanup := func() error {
		nc.Close()
		return nil
	}
	return pub, outbox, cleanup, nil
}


