	"github.com/nats-io/nkeys"
	"github.com/stretchr/testify/require"
)

// natsCreds writes a throwaway nkey seed file and a self-signed CA bundle,
// returning their paths. P0-13 made SetupNATS fail closed (TLS + nkey are
// mandatory), so a test that wants to reach the DIAL at all has to supply
// both — passing empty strings now short-circuits on validation and never
// exercises the connect path.
func natsCreds(t *testing.T) (credsFile, caFile string) {
	t.Helper()
	dir := t.TempDir()

	kp, err := nkeys.CreateUser()
	require.NoError(t, err)
	seed, err := kp.Seed()
	require.NoError(t, err)
	credsFile = filepath.Join(dir, "svc.creds")
	require.NoError(t, os.WriteFile(credsFile, append(seed, '\n'), 0o600))

	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	tmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(1),
		Subject:               pkix.Name{CommonName: "test-ca"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(24 * time.Hour),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
		BasicConstraintsValid: true,
		IsCA:                  true,
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	require.NoError(t, err)
	caFile = filepath.Join(dir, "ca.crt")
	require.NoError(t, os.WriteFile(caFile,
		pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), 0o600))

	return credsFile, caFile
}

// TestSetupNATS_EmptyURL verifies that SetupNATS returns an error when
// natsURL is empty (no NATS connection needed — pure validation path).
func TestSetupNATS_EmptyURL(t *testing.T) {
	_, _, _, err := SetupNATS(context.Background(), "", "", "", "")
	require.Error(t, err, "empty natsURL must return an error")
	require.Contains(t, err.Error(), "natsURL required")
}

// TestSetupNATS_MissingCredsOrCA_ReturnsError pins P0-13's fail-closed
// contract: TLS + nkey are mandatory, so a missing creds file or CA bundle is
// an error rather than a silent downgrade to a plaintext/unauthenticated
// connection. Deliberately uses an unreachable address so that a regression
// which DID skip the auth requirement could not pass here by quietly
// succeeding — with RetryOnFailedConnect it would return nil, not an error,
// and the assertion below would catch it.
func TestSetupNATS_MissingCredsOrCA_ReturnsError(t *testing.T) {
	credsFile, caFile := natsCreds(t)
	for _, tc := range []struct{ name, creds, ca string }{
		{"no creds", "", caFile},
		{"no ca", credsFile, ""},
		{"neither", "", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, _, _, err := SetupNATS(
				context.Background(), "nats://127.0.0.1:19999", tc.creds, tc.ca, "test_outbox",
			)
			require.Error(t, err, "missing creds/CA must fail closed")
		})
	}
}

// TestSetupNATS_UnreachableURL_SucceedsImmediately pins the deliberate
// behavior change from routing SetupNATS through the retrying connect
// posture: with RetryOnFailedConnect enabled, nats.Connect no longer fails
// fast against a syntactically valid but currently unreachable server — it
// returns successfully and keeps retrying the connection in the background
// (see nats.go's handling of Opts.RetryOnFailedConnect around the
// initial-connect error path). notifications-svc is a publisher/outbox site,
// so it opts into this retrying variant like org-svc, agents-svc, and
// identity-svc's publishers — unlike its own cmd/server/main.go relay
// connection and ws-gateway/the migrators, which keep the fail-fast
// DefaultConnectOptions per the natsconn package ruling.
//
// Post-P0-13 this needs REAL creds/CA: SetupNATS now dials through
// eventbus.Connect, which rejects empty ones before ever reaching the
// retry path, so supplying blanks would make this test pass for the wrong
// reason (validation error, not a tolerated unreachable connect).
func TestSetupNATS_UnreachableURL_SucceedsImmediately(t *testing.T) {
	credsFile, caFile := natsCreds(t)
	// Use an address on a port that is guaranteed to refuse connections.
	pub, outbox, cleanup, err := SetupNATS(
		context.Background(), "nats://127.0.0.1:19999", credsFile, caFile, "test_outbox",
	)
	require.NoError(t, err, "RetryOnFailedConnect must not fail SetupNATS on an unreachable initial connect")
	require.NotNil(t, pub)
	require.NotNil(t, outbox)
	require.NotNil(t, cleanup)
	require.NoError(t, cleanup())
}


