package events

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
)

// Relay polls notifications.event_outbox for undrained rows and publishes each
// to the NATS subject stored on the row. After a successful publish it sets
// drained_at = now().
//
// Concurrency note (slice 1 known limit): one relay goroutine per replica is
// sufficient for slice 1 throughput. If publish fails, drained_at is left NULL
// and the relay retries on the next tick. JetStream's Nats-Msg-Id dedup window
// prevents duplicate delivery if a row is published but drained_at is not
// written before a crash.
//
// The relay receives a *pgxpool.Pool that MUST use a BYPASSRLS (superuser or
// dedicated relay) Postgres role because the event_outbox table has RLS enabled
// with app.current_org_id scoping. The relay drains across all org IDs in a
// single poll and cannot set a per-row tenant GUC before reading.
// In production, cmd/server/main.go passes the admin pool from POSTGRES_ADMIN_DSN.
type Relay struct {
	pool     *pgxpool.Pool
	js       jetstream.JetStream
	interval time.Duration
	logger   *slog.Logger
}

// defaultPollInterval is the outbox poll frequency used when NewRelay receives
// a zero interval. Exported as a package-level constant so unit tests can assert
// the default without hardcoding the value.
const defaultPollInterval = 200 * time.Millisecond

// NewRelay constructs a Relay. pool must connect as a BYPASSRLS role.
// interval controls how often the outbox is polled; zero defaults to defaultPollInterval.
func NewRelay(pool *pgxpool.Pool, js jetstream.JetStream, interval time.Duration) *Relay {
	if interval == 0 {
		interval = defaultPollInterval
	}
	return &Relay{
		pool:     pool,
		js:       js,
		interval: interval,
		logger:   slog.Default(),
	}
}

// NewRelayWithLogger constructs a Relay with a custom logger.
func NewRelayWithLogger(pool *pgxpool.Pool, js jetstream.JetStream, interval time.Duration, logger *slog.Logger) *Relay {
	r := NewRelay(pool, js, interval)
	if logger != nil {
		r.logger = logger
	}
	return r
}

// Run polls the outbox until ctx is cancelled. It returns ctx.Err() on shutdown
// and does NOT return on individual drain failures (logs and retries next tick).
func (r *Relay) Run(ctx context.Context) error {
	t := time.NewTicker(r.interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-t.C:
			if err := r.drainOnce(ctx); err != nil {
				r.logger.ErrorContext(ctx, "relay drain error", "err", err)
				// Continue — retry on next tick.
			}
		}
	}
}

// outboxRow holds the fields fetched from event_outbox for a single drain pass.
type outboxRow struct {
	id        string
	orgID     string
	subject   string
	payload   []byte
	natsMsgID string
	// userID is the notification's recipient (event_outbox.user_id), used to
	// stamp x-user-id so ws-gateway's Router delivers to only that user's
	// sessions instead of broadcasting to the whole org (P1-08). Empty for
	// any pre-fix row inserted before the column existed.
	userID string
}

// drainOnce claims up to 100 undrained rows under a transaction with
// FOR UPDATE SKIP LOCKED and publishes each one. On publish success it sets
// drained_at = now() for that row; on publish failure it leaves drained_at NULL
// so the next tick retries. The batch commits at the end.
func (r *Relay) drainOnce(ctx context.Context) error {
	conn, err := r.pool.Acquire(ctx)
	if err != nil {
		return fmt.Errorf("acquire connection: %w", err)
	}
	defer conn.Release()

	tx, err := conn.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	// Claim a disjoint batch via FOR UPDATE SKIP LOCKED so that multiple relay
	// replicas don't double-publish: rows locked by another replica's tx are
	// skipped here and claimed by that replica. Mirrors eventbus/outbox.go.
	// Scan the whole batch and close the cursor BEFORE issuing the per-row
	// UPDATEs so the cursor doesn't conflict with this tx's Exec.
	rows, err := tx.Query(ctx, `
		SELECT id::text, org_id::text, subject, payload, nats_msg_id, COALESCE(user_id::text, '')
		FROM notifications.event_outbox
		WHERE drained_at IS NULL
		ORDER BY created_at
		LIMIT 100
		FOR UPDATE SKIP LOCKED`)
	if err != nil {
		return fmt.Errorf("query pending outbox: %w", err)
	}

	var batch []outboxRow
	for rows.Next() {
		var row outboxRow
		if err := rows.Scan(&row.id, &row.orgID, &row.subject, &row.payload, &row.natsMsgID, &row.userID); err != nil {
			rows.Close()
			return fmt.Errorf("scan outbox row: %w", err)
		}
		batch = append(batch, row)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate outbox rows: %w", err)
	}

	for _, row := range batch {
		if err := r.publish(ctx, row); err != nil {
			// Log and continue — next tick will retry this row.
			r.logger.ErrorContext(ctx, "relay publish failed",
				"outbox_id", row.id,
				"subject", row.subject,
				"err", err,
			)
			continue
		}

		// Mark drained after successful publish.
		if _, err := tx.Exec(ctx, `
			UPDATE notifications.event_outbox
			SET drained_at = now()
			WHERE id = $1`, row.id); err != nil {
			// If we can't mark drained, log it — JetStream dedup covers re-publish.
			r.logger.ErrorContext(ctx, "relay mark drained failed",
				"outbox_id", row.id,
				"err", err,
			)
		}
	}
	return tx.Commit(ctx)
}

// natsHeaderCarrier adapts nats.Header to the OTel TextMapCarrier interface
// so the global propagator can inject traceparent/tracestate into NATS headers.
type natsHeaderCarrier struct{ h nats.Header }

func (c natsHeaderCarrier) Get(key string) string { return c.h.Get(key) }
func (c natsHeaderCarrier) Set(key, val string)   { c.h.Set(key, val) }
func (c natsHeaderCarrier) Keys() []string        { return nil } // extract path — not needed

// publish sends one outbox row to NATS JetStream with the required headers.
// A child span "events.Relay.publish" is started and the W3C traceparent header
// is injected into the NATS message so downstream consumers can continue the trace.
func (r *Relay) publish(ctx context.Context, row outboxRow) error {
	tracer := otel.Tracer(tracerName)
	publishCtx, span := tracer.Start(ctx, "events.Relay.publish")
	defer span.End()

	span.SetAttributes(
		attribute.String("outbox_id", row.id),
		attribute.String("nats_subject", row.subject),
		attribute.String("nats_msg_id", row.natsMsgID),
	)

	msg := &nats.Msg{
		Subject: row.subject,
		Data:    row.payload,
		Header:  nats.Header{},
	}
	// Required headers per spec.
	msg.Header.Set("Nats-Msg-Id", row.natsMsgID)
	msg.Header.Set("content-type", "application/x-protobuf")
	msg.Header.Set("x-tenant-id", row.orgID)
	// P1-08: without this, ws-gateway's Router treats every frame as
	// broadcast-to-org (empty TargetUserID) and delivers a notification
	// meant for one user to every session in the org. row.userID is empty
	// only for a row inserted before the user_id column existed.
	if row.userID != "" {
		msg.Header.Set("x-user-id", row.userID)
	}

	// Inject W3C traceparent so the trace continues in NATS subscribers.
	otel.GetTextMapPropagator().Inject(publishCtx, natsHeaderCarrier{h: msg.Header})

	if _, err := r.js.PublishMsg(publishCtx, msg); err != nil {
		return fmt.Errorf("PublishMsg subject=%s: %w", row.subject, err)
	}
	return nil
}


