	require.Equal(t, 1, countUndrainedOutboxRows(t, adminDSN), "row must be undrained before relay")

	// Run the relay for one tick (poll interval 50ms, timeout 500ms).
	// The relay uses adminPool (BYPASSRLS) to read across all orgs.
	relay := events.NewRelay(adminPool, js, 50*time.Millisecond)
	relayCtx, relayCancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer relayCancel()
	_ = relay.Run(relayCtx) // returns on ctx cancel

	// After drain, the row's drained_at must be set.
	require.Equal(t, 0, countUndrainedOutboxRows(t, adminDSN), "row must be drained after relay tick")

