// Package events — relay unit tests (no Docker required).
//
// These tests cover drainOnce error paths using a closed pool (acquire fails
// immediately, no container needed) and a cancelled-context path for Run.
package events

import (
	"context"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/stretchr/testify/require"
)

// TestRelay_DrainOnce_AcquireError verifies that drainOnce returns an error
// when it cannot acquire a connection from a closed pool.
func TestRelay_DrainOnce_AcquireError(t *testing.T) {
	// Build a pool config pointing to a valid-looking DSN, open it, then
	// immediately close it so Acquire fails without touching the network.
	cfg, err := pgxpool.ParseConfig("postgres://localhost/nonexistent?connect_timeout=1")
	require.NoError(t, err)

	// Create pool from config (no connection attempt yet).
	pool, err := pgxpool.NewWithConfig(context.Background(), cfg)
	require.NoError(t, err)
	pool.Close() // pool is closed; Acquire will return an error immediately

	relay := NewRelay(pool, nil, 50*time.Millisecond)

	// drainOnce must return an error when the pool is closed.
	err = relay.drainOnce(context.Background())
	require.Error(t, err, "drainOnce must return an error when pool is closed")
	require.Contains(t, err.Error(), "acquire connection")
}

// TestRelay_Run_StopsOnContextCancel verifies that Run returns ctx.Err()
// when the context is cancelled (using a no-op pool that never connects).
func TestRelay_Run_StopsOnContextCancel(t *testing.T) {
	cfg, err := pgxpool.ParseConfig("postgres://localhost/nonexistent?connect_timeout=1")
	require.NoError(t, err)

	pool, err := pgxpool.NewWithConfig(context.Background(), cfg)
	require.NoError(t, err)
	pool.Close()

	relay := NewRelay(pool, nil, 50*time.Millisecond)

	ctx, cancel := context.WithTimeout(context.Background(), 150*time.Millisecond)
	defer cancel()

	// Run will drain once (fail silently), then ctx expires.
	err = relay.Run(ctx)
	// Run returns ctx.Err() on shutdown.
	require.Error(t, err, "Run must return context error on shutdown")
	require.ErrorIs(t, err, context.DeadlineExceeded)
}


