// Package events implements the transactional outbox pipeline for
// notifications-svc.
//
// Concurrency note (slice 1 known limit): only one relay instance per service
// replica is run. SELECT ... FOR UPDATE SKIP LOCKED is not used in slice 1
// because a single relay goroutine per replica is sufficient for the expected
// notification volume. Multi-replica deployments will see duplicate work
// suppressed at the JetStream Nats-Msg-Id dedup layer; the outbox row's
// drained_at IS NOT NULL guard prevents double-draining within the same
// replica. A follow-up slice will add FOR UPDATE SKIP LOCKED when horizontal
// scale of notifications-svc is required.
package events

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/timestamppb"

	dblib "github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
	notifv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/notifications/v1"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
)

const tracerName = "notifications-svc/events"

// InsertParams carries all fields needed to create a notification + outbox row
// in a single atomic transaction.
type InsertParams struct {
	OrgID           uuid.UUID
	RecipientUserID uuid.UUID
	Kind            repo.NotificationsNotificationKind
	Title           string
	Snippet         string // <= 140 chars
	Monogram        string // single display character
	MonogramBg      string // hex color, e.g. "#1A4FD6"
	SourceEventID   uuid.UUID
	// TargetID is an opaque per-kind navigation target (e.g. conversation_id
	// for MESSAGE_RECEIVED). Empty string is stored as SQL NULL.
	TargetID string

	// ForceOutboxErr is a test-only knob. When true, Insert deliberately
	// errors on the outbox INSERT to verify transactional rollback. Must
	// never be set in production callers.
	ForceOutboxErr bool
}

// Insert writes a notification row and an outbox row inside a single pgx.Tx.
// If either INSERT fails, both are rolled back.
//
// The nats_msg_id is computed as hex(sha256(source_event_id || recipient_user_id))[:16].
// The outbox subject is "notifications.user.created.<org_id>".
// The outbox payload is a serialized NotificationCreated proto.
//
// A span named "events.Insert" is started on the global tracer and ends when
// Insert returns. Callers should pass a context carrying an active span so the
// insert span is recorded as a child.
func Insert(ctx context.Context, pool *dblib.Pool, p InsertParams) error {
	tracer := otel.Tracer(tracerName)
	ctx, span := tracer.Start(ctx, "events.Insert")
	defer span.End()

	span.SetAttributes(
		attribute.String("org_id", p.OrgID.String()),
		attribute.String("recipient_user_id", p.RecipientUserID.String()),
		attribute.String("kind", string(p.Kind)),
	)

	natsMsgID := computeNatsMsgID(p.SourceEventID, p.RecipientUserID)
	subject := fmt.Sprintf("notifications.user.created.%s", p.OrgID)

	return pool.WithTx(ctx, func(tx pgx.Tx) error {
		q := repo.New(tx)

		// 1. Insert the notification row.
		notifID, err := uuid.NewV7()
		if err != nil {
			return fmt.Errorf("uuid.NewV7: %w", err)
		}

		row, err := q.InsertNotification(ctx, repo.InsertNotificationParams{
			ID:              notifID,
			OrgID:           p.OrgID,
			RecipientUserID: p.RecipientUserID,
			Kind:            p.Kind,
			Title:           p.Title,
			Snippet:         p.Snippet,
			Monogram:        p.Monogram,
			MonogramBg:      p.MonogramBg,
			SourceEventID:   p.SourceEventID,
			NatsMsgID:       natsMsgID,
			TargetID:        ptrIfNotEmpty(p.TargetID),
		})
		if errors.Is(err, pgx.ErrNoRows) {
			// Duplicate nats_msg_id: a prior delivery already inserted this
			// notification and enqueued its outbox row. Idempotent no-op.
			return nil
		}
		if err != nil {
			return fmt.Errorf("InsertNotification: %w", err)
		}

		// 2. Build the NotificationCreated payload.
		payload, err := buildPayload(row, p.OrgID, p.RecipientUserID, natsMsgID)
		if err != nil {
			return fmt.Errorf("buildPayload: %w", err)
		}

		// ForceOutboxErr is a test-only knob that exercises the rollback path.
		if p.ForceOutboxErr {
			return errors.New("forced outbox error (test-only)")
		}

		// 3. Insert the outbox row in the same tx.
		outboxID, err := uuid.NewV7()
		if err != nil {
			return fmt.Errorf("uuid.NewV7 (outbox): %w", err)
		}
		if err := q.EnqueueOutbox(ctx, repo.EnqueueOutboxParams{
			ID:        outboxID,
			OrgID:     p.OrgID,
			Subject:   subject,
			Payload:   payload,
			NatsMsgID: natsMsgID,
			// P1-08: the relay stamps this onto the published NATS
			// message's x-user-id header so ws-gateway's Router
			// delivers the frame only to the recipient's sessions,
			// not the whole org.
			UserID: &p.RecipientUserID,
		}); err != nil {
			return fmt.Errorf("EnqueueOutbox: %w", err)
		}

		return nil
	})
}

// computeNatsMsgID computes hex(sha256(sourceEventID || recipientUserID))[:16].
// The truncation to 16 hex chars (8 bytes) matches the spec. The full sha256 is
// retained in memory but only 16 chars are stored; this is sufficient uniqueness
// for the (source_event_id, recipient_user_id) pair.
func computeNatsMsgID(sourceEventID, recipientUserID uuid.UUID) string {
	h := sha256.New()
	h.Write(sourceEventID[:])
	h.Write(recipientUserID[:])
	return hex.EncodeToString(h.Sum(nil))[:16]
}

// buildPayload serializes a NotificationCreated proto from the inserted row.
func buildPayload(
	row repo.NotificationsNotification,
	orgID uuid.UUID,
	recipientUserID uuid.UUID,
	natsMsgID string,
) ([]byte, error) {
	kind := repoKindToProto(row.Kind)

	var createdAt *timestamppb.Timestamp
	if row.CreatedAt.Valid {
		createdAt = timestamppb.New(row.CreatedAt.Time)
	} else {
		createdAt = timestamppb.New(time.Now())
	}

	evt := &notifv1.NotificationCreated{
		EventId:         natsMsgID,
		OrgId:           orgID.String(),
		RecipientUserId: recipientUserID.String(),
		OccurredAt:      createdAt,
		Notification: &notifv1.Notification{
			Id:            row.ID.String(),
			Kind:          kind,
			Title:         row.Title,
			Snippet:       row.Snippet,
			Monogram:      row.Monogram,
			MonogramBg:    row.MonogramBg,
			CreatedAt:     createdAt,
			SourceEventId: row.SourceEventID.String(),
			TargetId:      derefStr(row.TargetID),
		},
	}

	b, err := proto.Marshal(evt)
	if err != nil {
		return nil, fmt.Errorf("proto.Marshal: %w", err)
	}
	return b, nil
}

// ptrIfNotEmpty returns a *string for non-empty s, else nil (stored as SQL NULL).
func ptrIfNotEmpty(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// derefStr returns the pointed-to string, or "" when nil.
func derefStr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// repoKindToProto maps the sqlc-generated enum to the proto enum.
func repoKindToProto(k repo.NotificationsNotificationKind) notifv1.NotificationKind {
	switch k {
	case repo.NotificationsNotificationKindInviteAccepted:
		return notifv1.NotificationKind_NOTIFICATION_KIND_INVITE_ACCEPTED
	case repo.NotificationsNotificationKindMembershipAdded:
		return notifv1.NotificationKind_NOTIFICATION_KIND_MEMBERSHIP_ADDED
	case repo.NotificationsNotificationKindWorkspaceSwitched:
		return notifv1.NotificationKind_NOTIFICATION_KIND_WORKSPACE_SWITCHED
	case repo.NotificationsNotificationKindIngestCompleted:
		return notifv1.NotificationKind_NOTIFICATION_KIND_INGEST_COMPLETED
	case repo.NotificationsNotificationKindIngestFailed:
		return notifv1.NotificationKind_NOTIFICATION_KIND_INGEST_FAILED
	case repo.NotificationsNotificationKindRoleChanged:
		return notifv1.NotificationKind_NOTIFICATION_KIND_ROLE_CHANGED
	case repo.NotificationsNotificationKindLoginNewDevice:
		return notifv1.NotificationKind_NOTIFICATION_KIND_LOGIN_NEW_DEVICE
	case repo.NotificationsNotificationKindMessageReceived:
		return notifv1.NotificationKind_NOTIFICATION_KIND_MESSAGE_RECEIVED
	default:
		return notifv1.NotificationKind_NOTIFICATION_KIND_UNSPECIFIED
	}
}


