// startTLSAuthNATS boots a nats:2.10-alpine container with a throwaway
// self-signed TLS cert and a single nkey account (jetstream enabled,
// unrestricted permissions) — mirroring the TLS+nkey shape of
// platform/config/nats/nats-server.conf.tmpl (P0-13). SetupNATS's
// CredsFile/RootCAFile checks are fail-closed (see
// platform/libs/go/eventbus.Connect), so this test needs real creds/CA to
// connect at all; plain testcontainers/modules/nats.Run boots a
// plaintext/no-auth server that SetupNATS can no longer reach.
//
// Mirrors the pattern in
// platform/libs/go/eventbus/integration/nats_tls_auth_test.go and
// services/migrator-org/tests/integration/helpers.go's StartNATS.
func startTLSAuthNATS(t *testing.T) (url, credsFile, caFile string, cleanup func()) {
	t.Helper()
	ctx := context.Background()

	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	caTmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(1),
		Subject:               pkix.Name{CommonName: "test-nats-ca"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(24 * time.Hour),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
