//go:build integration

// Package events — CR-M11 integration test for concurrent-relay safety.
//
// CR-M11: drainOnce must claim outbox rows with FOR UPDATE SKIP LOCKED inside a
// transaction so that multiple relay replicas claim DISJOINT batches. Today's
// drainOnce runs a lockless SELECT on a plain pooled conn (no tx, no row lock),
// so it ignores rows already locked by a concurrent relay's transaction and
// re-publishes/re-drains them — double work + an UPDATE race.
//
// This test pins the FOR UPDATE SKIP LOCKED behavior directly (Option A): a
// separate transaction locks the only pending outbox row, then the relay runs.
// A correct (post-fix) relay SKIPs the locked row and leaves it undrained; the
// current lockless relay drains it anyway → RED.
//
// Run: go test -tags=integration -run TestRelay_SkipsRowsLockedByConcurrentTx ./internal/events/...
package events_test

import (
	"context"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/events"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
)

// TestRelay_SkipsRowsLockedByConcurrentTx asserts that the relay does NOT drain
// an outbox row that is already row-locked by a concurrent transaction. This is
// exactly the FOR UPDATE SKIP LOCKED contract that lets multiple relay replicas
// claim disjoint batches without double-publishing.
//
// Setup: seed one undrained outbox row, then open a SEPARATE transaction (on its
// own BYPASSRLS pool) that runs the same claim query the fixed relay will run —
// SELECT ... WHERE drained_at IS NULL ... FOR UPDATE SKIP LOCKED — locking that
// single row and holding the tx open. With the row locked, the relay runs.
//
// Expected (post-fix): the relay's own FOR UPDATE SKIP LOCKED SELECT skips the
// locked row and publishes ZERO messages to NATS.
// Today (lockless drainOnce): the relay SELECT ignores the lock and PUBLISHES
// the row to NATS (its drained_at UPDATE then blocks on the row lock, but the
// double-publish has already happened) → 1 message lands on the stream → this
// assertion FAILS, proving the bug: locked rows are not skipped, so concurrent
// relay replicas re-publish each other's claimed rows.
//
// We assert on the published-message count rather than drained_at because the
// lockless relay's drained_at UPDATE is incidentally blocked by the very row
// lock under test — so drained_at would mask the double-publish. The publish is
// the real harm CR-M11 fixes, and it is what FOR UPDATE SKIP LOCKED prevents.
func TestRelay_SkipsRowsLockedByConcurrentTx(t *testing.T) {
	if testing.Short() {
		t.Skip("integration: requires Docker")
	}

	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()

	adminDSN, pool := startTestPostgres(t)
	// The relay reads with a BYPASSRLS pool so it can see rows across all orgs.
	relayPool := startAdminPool(t, adminDSN)
	js, _ := startTestNATS(t, ctx)

	orgID := uuid.New()
	userID := uuid.New()
	sourceEventID := uuid.New()

	// Seed exactly one notification + outbox row via the production Insert path.
	params := events.InsertParams{
		OrgID:           orgID,
		RecipientUserID: userID,
		Kind:            repo.NotificationsNotificationKindMembershipAdded,
		Title:           "Skip-locked test",
		Snippet:         "Row should be skipped while locked",
		Monogram:        "S",
		MonogramBg:      "#1A4FD6",
		SourceEventID:   sourceEventID,
	}
	require.NoError(t, events.Insert(tenantCtx(orgID, userID), pool, params))
	require.Equal(t, 1, countUndrainedOutboxRows(t, adminDSN),
		"precondition: exactly one undrained outbox row")

	// Open a SEPARATE BYPASSRLS pool and lock the pending row with the same
	// claim query the fixed relay will use. Holding this tx open simulates a
	// concurrent relay replica that has already claimed the batch.
	lockPool := startAdminPool(t, adminDSN)
	lockTx, err := lockPool.Begin(ctx)
	require.NoError(t, err)
	t.Cleanup(func() { _ = lockTx.Rollback(context.Background()) })

	var lockedID string
	err = lockTx.QueryRow(ctx, `
		SELECT id::text
		FROM notifications.event_outbox
		WHERE drained_at IS NULL
		ORDER BY created_at
		LIMIT 100
		FOR UPDATE SKIP LOCKED`).Scan(&lockedID)
	require.NoError(t, err, "lock tx must lock the one pending row")
	require.NotEmpty(t, lockedID)

	// Run the relay while the row is locked by lockTx.
	relay := events.NewRelay(relayPool, js, 50*time.Millisecond)
	relayCtx, relayCancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer relayCancel()
	_ = relay.Run(relayCtx) // returns on ctx cancel

	// A relay that honors FOR UPDATE SKIP LOCKED never SELECTs the locked row, so
	// it publishes NOTHING. The current lockless relay reads + publishes it →
	// exactly one message on the NOTIFICATIONS stream → this assertion FAILS,
	// proving locked rows are not skipped (concurrent replicas would double-publish).
	streamHandle, err := js.Stream(ctx, "NOTIFICATIONS")
	require.NoError(t, err)
	streamInfo, err := streamHandle.Info(ctx)
	require.NoError(t, err)
	require.Equal(t, uint64(0), streamInfo.State.Msgs,
		"relay must SKIP the row locked by a concurrent tx and publish nothing")

	// Release the lock (also handled by t.Cleanup; explicit here for clarity).
	require.NoError(t, lockTx.Rollback(ctx))
}


