	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
)

// startAdminPool opens a raw pgxpool as the superuser (BYPASSRLS) for relay use.
func startAdminPool(t *testing.T, adminDSN string) *pgxpool.Pool {
	t.Helper()
	ctx := context.Background()
	pool, err := pgxpool.New(ctx, adminDSN)
	require.NoError(t, err)
	t.Cleanup(pool.Close)
	return pool
}

// startTestNATS boots a NATS testcontainer with JetStream enabled.
// It creates the NOTIFICATIONS stream scoped to "notifications.>" subjects.
// Returns both the JetStream interface and the raw *nats.Conn for core subscriptions.
func startTestNATS(t *testing.T, ctx context.Context) (jetstream.JetStream, *nats.Conn) {
	t.Helper()

	nc2, err := natscontainer.Run(ctx, "nats:2.10-alpine")
	require.NoError(t, err)
	t.Cleanup(func() { _ = nc2.Terminate(ctx) })

	natsURL, err := nc2.ConnectionString(ctx)
	require.NoError(t, err)

	nc, err := nats.Connect(natsURL)
	require.NoError(t, err)
	t.Cleanup(nc.Close)

	js, err := jetstream.New(nc)
	require.NoError(t, err)

	// Create the NOTIFICATIONS stream. Without a stream, PublishMsg returns
	// "nats: no responders available for request".
	// Duplicates window of 5 minutes covers the relay re-publish dedup test.
	_, err = js.CreateStream(ctx, jetstream.StreamConfig{
		Name:       "NOTIFICATIONS",
		Subjects:   []string{"notifications.>"},
		Duplicates: 5 * time.Minute,
	})
	require.NoError(t, err)

	return js, nc
}

// countUndrainedOutboxRows returns the count of rows where drained_at IS NULL.
func countUndrainedOutboxRows(t *testing.T, adminDSN string) int {
	t.Helper()
	db, err := sql.Open("pgx", adminDSN)
	require.NoError(t, err)
	defer func() { _ = db.Close() }()
	var n int
	require.NoError(t, db.QueryRow(
		`SELECT count(*) FROM notifications.event_outbox WHERE drained_at IS NULL`,
	).Scan(&n))
	return n
}

// readFirstOutboxNatsMsgID returns the nats_msg_id of the first outbox row.
func readFirstOutboxNatsMsgID(t *testing.T, adminDSN string) string {
	t.Helper()
	db, err := sql.Open("pgx", adminDSN)
	require.NoError(t, err)
	defer func() { _ = db.Close() }()
	var id string
	require.NoError(t, db.QueryRow(
		`SELECT nats_msg_id FROM notifications.event_outbox ORDER BY created_at LIMIT 1`,
	).Scan(&id))
	return id
}

// ---------------------------------------------------------------------------
// D2: relay drains rows to NATS; drained_at is set after drain.
// ---------------------------------------------------------------------------

func TestRelay_DrainsPendingRowsToNATS(t *testing.T) {
	if testing.Short() {
		t.Skip("integration: requires Docker")
	}

	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()

	adminDSN, pool := startTestPostgres(t)
	// Relay requires a BYPASSRLS (superuser) pool so it can read all org rows.
	adminPool := startAdminPool(t, adminDSN)
	js, nc := startTestNATS(t, ctx)

	orgID := uuid.New()
	userID := uuid.New()
	sourceEventID := uuid.New()

	// Subscribe on the core NATS connection BEFORE Insert so we don't miss the message.
	subject := "notifications.user.created." + orgID.String()
	sub, err := nc.SubscribeSync(subject)
	require.NoError(t, err)
	t.Cleanup(func() { _ = sub.Unsubscribe() })

	// Insert a notification (and outbox row) via events.Insert.
	params := events.InsertParams{
		OrgID:           orgID,
		RecipientUserID: userID,
		Kind:            repo.NotificationsNotificationKindMembershipAdded,
		Title:           "You were added to a workspace",
		Snippet:         "Welcome to Acme Corp",
		Monogram:        "A",
		MonogramBg:      "#1A4FD6",
		SourceEventID:   sourceEventID,
	}
	tCtx := tenantCtx(orgID, userID)
	require.NoError(t, events.Insert(tCtx, pool, params))

	// Before drain, the outbox row is pending.
	require.Equal(t, 1, countUndrainedOutboxRows(t, adminDSN), "row must be undrained before relay")

	// Run the relay for one tick (poll interval 50ms, timeout 500ms).
	// The relay uses adminPool (BYPASSRLS) to read across all orgs.
	relay := events.NewRelay(adminPool, js, 50*time.Millisecond)
	relayCtx, relayCancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer relayCancel()
	_ = relay.Run(relayCtx) // returns on ctx cancel

	// After drain, the row's drained_at must be set.
	require.Equal(t, 0, countUndrainedOutboxRows(t, adminDSN), "row must be drained after relay tick")

	// A message must have arrived on the correct NATS subject.
	msg, err := sub.NextMsg(2 * time.Second)
	require.NoError(t, err, "expected a NATS message on "+subject)
	require.NotEmpty(t, msg.Data, "message payload must not be empty")

	// P1-08: the relay must stamp x-user-id with the notification's
	// recipient so ws-gateway's Router delivers it to only that user's
	// sessions, not every session in the org.
	require.Equal(t, userID.String(), msg.Header.Get("x-user-id"),
		"relay must stamp x-user-id with the notification's recipient")
}

// ---------------------------------------------------------------------------
// Publish-error path: relay logs the error and leaves the row undrained.
// This covers the "publish failed" continue branch in drainOnce.
// ---------------------------------------------------------------------------

// TestRelay_PublishError_RowStaysUndrained verifies that when JetStream
// publish fails (no stream configured), the relay logs the error, continues,
// and leaves drained_at NULL so the next tick retries.
func TestRelay_PublishError_RowStaysUndrained(t *testing.T) {
	if testing.Short() {
		t.Skip("integration: requires Docker")
	}

	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()

	adminDSN, pool := startTestPostgres(t)
	adminPool := startAdminPool(t, adminDSN)

	// Start NATS but do NOT create any stream — PublishMsg will fail with
	// "nats: no responders available for request".
	natsCtx := ctx
	nc2, err := natscontainer.Run(natsCtx, "nats:2.10-alpine")
	require.NoError(t, err)
	t.Cleanup(func() { _ = nc2.Terminate(natsCtx) })

	natsURL, err := nc2.ConnectionString(natsCtx)
	require.NoError(t, err)

	nc, err := nats.Connect(natsURL)
	require.NoError(t, err)
	t.Cleanup(nc.Close)

	js, err := jetstream.New(nc)
	require.NoError(t, err)
	// Intentionally: no js.CreateStream call — publish will fail.

	orgID := uuid.New()
	userID := uuid.New()
	sourceEventID := uuid.New()

	// Insert a notification + outbox row.
	params := events.InsertParams{
		OrgID:           orgID,
		RecipientUserID: userID,
		Kind:            repo.NotificationsNotificationKindRoleChanged,
		Title:           "Publish error test",
		Snippet:         "Should remain undrained",
		Monogram:        "P",
		MonogramBg:      "#FF0000",
		SourceEventID:   sourceEventID,
	}
	tCtx := tenantCtx(orgID, userID)
	require.NoError(t, events.Insert(tCtx, pool, params))
	require.Equal(t, 1, countUndrainedOutboxRows(t, adminDSN), "row must be undrained before relay")

	// Run relay — publish will fail (no stream), relay logs error and continues.
	relay := events.NewRelay(adminPool, js, 50*time.Millisecond)
	relayCtx, relayCancel := context.WithTimeout(ctx, 300*time.Millisecond)
	defer relayCancel()
	_ = relay.Run(relayCtx)

	// The row must still be undrained because publish failed.
	require.Equal(t, 1, countUndrainedOutboxRows(t, adminDSN),
		"row must remain undrained when publish fails")
}

// ---------------------------------------------------------------------------
// D3: Nats-Msg-Id matches outbox nats_msg_id; duplicate drain is a no-op.
// ---------------------------------------------------------------------------

func TestRelay_NatsMsgIDMatchesOutbox_AndDedupsOnSecondRun(t *testing.T) {
	if testing.Short() {
		t.Skip("integration: requires Docker")
	}

	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()

	adminDSN, pool := startTestPostgres(t)
	adminPool := startAdminPool(t, adminDSN)
	js, nc := startTestNATS(t, ctx)

	orgID := uuid.New()
	userID := uuid.New()
	sourceEventID := uuid.New()

	subject := "notifications.user.created." + orgID.String()

	// Core subscription to capture the first message.
	sub, err := nc.SubscribeSync(subject)
	require.NoError(t, err)
	t.Cleanup(func() { _ = sub.Unsubscribe() })

	// Insert notification + outbox row.
	params := events.InsertParams{
		OrgID:           orgID,
		RecipientUserID: userID,
		Kind:            repo.NotificationsNotificationKindInviteAccepted,
		Title:           "Dedup test",
		Snippet:         "Testing Nats-Msg-Id dedup",
		Monogram:        "D",
		MonogramBg:      "#1A4FD6",
		SourceEventID:   sourceEventID,
	}
	tCtx := tenantCtx(orgID, userID)
	require.NoError(t, events.Insert(tCtx, pool, params))

	// Read the outbox nats_msg_id before drain.
	outboxMsgID := readFirstOutboxNatsMsgID(t, adminDSN)
	require.NotEmpty(t, outboxMsgID)

	// Run relay FIRST time. Uses adminPool (BYPASSRLS) to read across all orgs.
	relay := events.NewRelay(adminPool, js, 50*time.Millisecond)
	run1Ctx, run1Cancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer run1Cancel()
	_ = relay.Run(run1Ctx)

	// Receive the first message and verify Nats-Msg-Id header.
	msg1, err := sub.NextMsg(2 * time.Second)
	require.NoError(t, err, "expected a NATS message on "+subject)
	gotMsgID := msg1.Header.Get("Nats-Msg-Id")
	require.Equal(t, outboxMsgID, gotMsgID,
		"Nats-Msg-Id header must equal outbox nats_msg_id")

	// Reset drained_at to simulate a crash between publish and drained_at update.
	adminDB, err := sql.Open("pgx", adminDSN)
	require.NoError(t, err)
	_, err = adminDB.Exec(`UPDATE notifications.event_outbox SET drained_at = NULL`)
	require.NoError(t, err)
	require.NoError(t, adminDB.Close())

	// Run relay SECOND time — same Nats-Msg-Id → JetStream dedup discards it.
	run2Ctx, run2Cancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer run2Cancel()
	_ = relay.Run(run2Ctx)

	// Count messages on the NOTIFICATIONS stream — must still be exactly 1.
	streamHandle, err := js.Stream(ctx, "NOTIFICATIONS")
	require.NoError(t, err)
	streamInfo, err := streamHandle.Info(ctx)
	require.NoError(t, err)
	require.Equal(t, uint64(1), streamInfo.State.Msgs,
		"JetStream dedup must prevent the second publish from landing as a new message")
}


