//go:build integration

// Package events — D5 OTel span propagation test.
//
// Verifies that:
//  1. events.Insert() starts a span.
//  2. The relay's drain + publish continues in the same trace.
//  3. The published NATS message carries a "traceparent" header.
//
// The test uses an in-memory SpanRecorder (no real OTLP exporter needed).
//
// Run: go test -tags=integration -run TestOTelSpanPropagation ./internal/events/...
package events_test

import (
	"context"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/stretchr/testify/require"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/propagation"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	"go.opentelemetry.io/otel/sdk/trace/tracetest"

	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/events"
	"github.com/zenithflowinc/omnicore-platform/services/notifications-svc/internal/repo"
)

// TestOTelSpanPropagation verifies:
//  1. A span is started during Insert() and recorded by the tracer.
//  2. The relay's publish operation starts a span recorded by the tracer.
//  3. The published NATS message carries a "traceparent" header.
//
// Slice 1 known limit: the relay is a background goroutine that does not have
// access to the original Insert() context (the outbox schema does not store
// traceparent). Therefore Insert and relay.publish spans are in different traces.
// The traceparent on the NATS message links the relay's own trace, enabling
// downstream consumers (ws-gateway) to continue that trace. A future slice can
// store traceparent in the outbox row to stitch the full chain.
func TestOTelSpanPropagation(t *testing.T) {
	if testing.Short() {
		t.Skip("integration: requires Docker")
	}

	// Wire up an in-memory span recorder as the global tracer provider.
	recorder := tracetest.NewSpanRecorder()
	tp := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(recorder))
	otel.SetTracerProvider(tp)
	// Set W3C TraceContext propagator so traceparent is injected into NATS headers.
	otel.SetTextMapPropagator(propagation.TraceContext{})
	t.Cleanup(func() {
		otel.SetTracerProvider(otel.GetTracerProvider())
	})

	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()

	adminDSN, pool := startTestPostgres(t)
	adminPool := startAdminPool(t, adminDSN)
	js, nc := startTestNATS(t, ctx)

	orgID := uuid.New()
	userID := uuid.New()
	sourceEventID := uuid.New()

	subject := "notifications.user.created." + orgID.String()
	sub, err := nc.SubscribeSync(subject)
	require.NoError(t, err)
	t.Cleanup(func() { _ = sub.Unsubscribe() })

	// Start a root span so Insert() can record a child span under it.
	rootCtx, rootSpan := tp.Tracer("test").Start(tenantCtx(orgID, userID), "test-root")

	// 1. Insert — must start a child span under rootSpan.
	params := events.InsertParams{
		OrgID:           orgID,
		RecipientUserID: userID,
		Kind:            repo.NotificationsNotificationKindInviteAccepted,
		Title:           "Span test",
		Snippet:         "OTel propagation test",
		Monogram:        "S",
		MonogramBg:      "#1A4FD6",
		SourceEventID:   sourceEventID,
	}
	require.NoError(t, events.Insert(rootCtx, pool, params))
	rootSpan.End()

	// 2. Run relay — must record an events.Relay.publish span.
	relay := events.NewRelay(adminPool, js, 50*time.Millisecond)
	relayCtx, relayCancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer relayCancel()
	_ = relay.Run(relayCtx)

	// 3. Receive the NATS message.
	msg, err := sub.NextMsg(3 * time.Second)
	require.NoError(t, err, "subscriber must receive message")

	// Verify traceparent header is present on the NATS message.
	traceparent := msg.Header.Get("traceparent")
	require.NotEmpty(t, traceparent, "NATS message must carry a traceparent header")

	// Verify that our events spans were recorded.
	ended := recorder.Ended()
	var insertSpan, publishSpan bool
	rootTraceID := rootSpan.SpanContext().TraceID()
	require.True(t, rootTraceID.IsValid(), "root trace_id must be valid")

	for _, s := range ended {
		switch s.Name() {
		case "events.Insert":
			insertSpan = true
			// Insert span must be a child of the root span (same trace).
			require.Equal(t, rootTraceID, s.SpanContext().TraceID(),
				"events.Insert span must share the root trace_id")
		case "events.Relay.publish":
			publishSpan = true
			// Relay publish span has its own trace (relay runs background context).
			// Verify the traceparent header matches the relay publish span's trace.
			require.True(t, s.SpanContext().TraceID().IsValid(),
				"events.Relay.publish span must have a valid trace_id")
		}
	}
	require.True(t, insertSpan, "events.Insert span must be recorded")
	require.True(t, publishSpan, "events.Relay.publish span must be recorded")
}



